@app.post('/api/contracts/{contract_id}/watermark-pdf')
def render_watermarked_contract(
    contract_id: int,
    body: WatermarkOptions,
    session: Session = Depends(get_session),
    user: User = Depends(get_current_user)
):
    contract = session.exec(
        select(LegalContract).where(LegalContract.id == contract_id, LegalContract.party_user_id == user.id)
    ).first()
    if not contract:
        raise HTTPException(status_code=404, detail="Contract not found")

    pdf_bytes = apply_pdf_watermark(contract.file_path, text=body.watermark_text)
    return Response(content=pdf_bytes, media_type="application/pdf")
